<body>
<main>
  <h1>Bevásárlólista</h1>
  <p class="hint">Írd be a terméket, válaszd ki a kategóriát, majd pipáld ki, amit megvettél. A lista automatikusan elmentődik.</p>
  <div class="sr-only" aria-live="polite" id="status"></div>

  <form class="add-row" id="addForm">
    <label class="sr-only" for="name">Termék neve</label>
    <input type="text" id="name" placeholder="Pl. paradicsom" autocomplete="off">
    <label class="sr-only" for="cat">Kategória</label>
    <select id="cat">
      <option value="zseg">Zöldség</option>
      <option value="pek">Pékáru</option>
      <option value="tej">Tejtermék</option>
      <option value="egy">Egyéb</option>
    </select>
    <button type="submit" class="primary">Hozzáad</button>
  </form>

  <div id="list"></div>
</main>
<script>
const KEY='shopping-list';
const CATS=[
  {id:'zseg',label:'Zöldség'},
  {id:'pek',label:'Pékáru'},
  {id:'tej',label:'Tejtermék'},
  {id:'egy',label:'Egyéb'}
];
let items=[];

function uid(){
  return Date.now().toString(36)+Math.random().toString(36).slice(2,7);
}
function announce(msg){document.getElementById('status').textContent=msg;}

function save(){
  if(window.alfy && window.alfy.storage){
    try{window.alfy.storage.set(KEY,items);}catch(e){}
  }
}
function load(){
  if(window.alfy && window.alfy.storage){
    return Promise.resolve(window.alfy.storage.get(KEY)).then(v=>{
      if(Array.isArray(v)) items=v;
    }).catch(()=>{});
  }
  return Promise.resolve();
}

function addItem(){
  const nameInput=document.getElementById('name');
  const name=nameInput.value.trim();
  if(!name){nameInput.focus(); return;}
  const cat=document.getElementById('cat').value;
  items.push({id:uid(),name:name,cat:cat,done:false});
  nameInput.value='';
  save();
  render();
  announce('Hozzáadva: '+name);
  nameInput.focus();
}

function toggle(id){
  const it=items.find(x=>x.id===id);
  if(it){it.done=!it.done; save(); render();}
}
function removeItem(id){
  const it=items.find(x=>x.id===id);
  items=items.filter(x=>x.id!==id);
  save(); render();
  if(it) announce('Törölve: '+it.name);
}
function clearChecked(){
  const n=items.filter(x=>x.done).length;
  items=items.filter(x=>!x.done);
  save(); render();
  announce(n+' tétel törölve.');
}

function itemRow(it){
  const li=document.createElement('li');
  li.className='item'+(it.done?' done':'');
  const cb=document.createElement('input');
  cb.type='checkbox'; cb.checked=it.done; cb.id='c-'+it.id;
  cb.addEventListener('change',()=>toggle(it.id));
  const lab=document.createElement('label');
  lab.htmlFor='c-'+it.id; lab.textContent=it.name;
  const del=document.createElement('button');
  del.className='del'; del.type='button'; del.textContent='×';
  del.setAttribute('aria-label','Törlés: '+it.name);
  del.addEventListener('click',()=>removeItem(it.id));
  li.append(cb,lab,del);
  return li;
}

function render(){
  const list=document.getElementById('list');
  list.innerHTML='';
  if(items.length===0){
    const e=document.createElement('div');
    e.className='empty';
    e.innerHTML='<h2>Még nincs semmi a listán</h2><p>Add hozzá az első terméket a fenti mezőben.</p>';
    const b=document.createElement('button');
    b.className='primary'; b.type='button'; b.textContent='Hozzáadás';
    b.addEventListener('click',()=>document.getElementById('name').focus());
    e.appendChild(b);
    list.appendChild(e);
    return;
  }
  const total=items.length, bought=items.filter(x=>x.done).length;
  CATS.forEach(c=>{
    const group=items.filter(x=>x.cat===c.id);
    if(group.length===0) return;
    const card=document.createElement('section');
    card.className='card';
    const head=document.createElement('div');
    head.className='card-head';
    const h=document.createElement('h2'); h.textContent=c.label;
    const cnt=document.createElement('span'); cnt.className='count';
    const gDone=group.filter(x=>x.done).length;
    cnt.textContent=gDone+' / '+group.length+' megvéve';
    head.append(h,cnt);
    const ul=document.createElement('ul');
    group.forEach(it=>ul.appendChild(itemRow(it)));
    card.append(head,ul);
    list.appendChild(card);
  });
  if(bought>0){
    const bar=document.createElement('div');
    bar.className='card';
    const p=document.createElement('div');
    p.style.marginBottom='12px';
    p.textContent='Összesen: '+total+' tétel, '+bought+' megvéve.';
    const clr=document.createElement('button');
    clr.type='button'; clr.textContent='Megvettek törlése';
    clr.addEventListener('click',clearChecked);
    bar.append(p,clr);
    list.appendChild(bar);
  }
}

document.getElementById('addForm').addEventListener('submit',e=>{e.preventDefault(); addItem();});

load().then(render);
</script>
</body>
</html>
